/* =========================================================================
   sql/36_solicitud_iniciativa_solicitante_admin.sql - Nueva solicitud de
   un ADM / MOD de dbo.UsuariosAdmin que NO esta en CatPersona.
                    ROLLBACK: _rollback_procedimiento.sql (solo _Crear) o
                              _rollback.sql (completo)
   ESTADO: PROPUESTA PARA REVISION. NO EJECUTADA EN LA VM NI APROBADA.
   Solo se corrio en bases DESECHABLES de LocalDB (GestionAdminPrueba_*,
   tools/tests/SolicitanteAdminPsoSqlLocalDbSmoke.cs).

   DEPENDE DE sql/35 (NombreSolicitante) y de sql/29 (_Crear con su hash).
     Orden: 35 -> 36 -> 37. Deshacer en orden inverso.

   QUE CAMBIA (una transaccion)
     + adm.fn_ClaveCorreo / adm.fn_ClaveNombre: la MISMA normalizacion del
       sitio (IdentidadAcuse.ClaveCorreo / ClaveNombre), con tablas
       generadas de .NET. Comparar SIEMPRE con COLLATE Latin1_General_100_BIN2.
     adm.SolicitudIniciativa
       SolicitanteNombre        NOT NULL -> NULL
       CK_SolicitudIniciativa_Fuente      CATPERSONA -> CATPERSONA | USUARIOSADMIN
       + CK_SolicitudIniciativa_FuenteNombre  sin nombre solo con USUARIOSADMIN
     adm.usp_SolicitudIniciativa_Crear (texto de sql/29 + lo de abajo)
       La base decide la fuente con sus tablas (no la presencia del nombre):
         CATPERSONA     el correo es de UNA fila vigente de CatPersona y su
                        nombre no se repite (51403 si el sitio no manda nombre)
         USUARIOSADMIN  si no: todas las filas de la cuenta en UsuariosAdmin
                        son ADM / MOD, con UN CorreoUsuario, y es el enviado.
                        El nombre sale de UsuariosAdmin.NombreSolicitante
                        (NULL valido); el del sitio no se usa. Dos nombres
                        distintos: 51418.
         otra cosa      51417 (cuenta en UsuariosAdmin mal configurada) o
                        51405 (como en sql/29).
       + @FuenteSolicitante / @NombreGuardado OUTPUT, opcionales al final:
         el sitio detecta 36 por @FuenteSolicitante (sys.parameters).
     NO cambia: filas, eventos, contador, AprobarYCrear (sql/32), Aprobar y
       Rechazar (sql/31), permisos, nada de dbo.

   DATOS: las filas actuales son CATPERSONA con nombre; cumplen los CHECK
     nuevos (se agregan WITH CHECK: quedan confiables).

   PRECONDICION (si no, ROLLBACK y no toca nada)
     _Crear = sql/29  0x518234C546F607D7FF3DA64DDB0BBE167002DA7BC31C6C897CF9A2C82050761A
     dbo.UsuariosAdmin.NombreSolicitante existe (sql/35).
     La tabla como la deja sql/29 (SolicitanteNombre NOT NULL, sin
     _FuenteNombre) o como la deja ESTA migracion (tras el rollback de
     procedimiento). Las funciones, si existen, se reemplazan.
   POSTCONDICION (si no, ROLLBACK)
     _Crear  0x0484CDBC320573111B3EE245FA1E225F83DC65E7078213DE1C4C275C70E51D5A, 21 parametros; funciones, columna nula y CHECK presentes.

   COMO CORRERLO (solo con OK explicito de este script)
       EXEC sys.sp_set_session_context N'aprobar_migracion', N'36';
     y el script completo (sqlcmd -b -I, o SSMS con el script entero).
     Una sola transaccion: si algo falla, ROLLBACK de todo.
   ========================================================================= */
IF DB_NAME() NOT LIKE N'GestionAdminPrueba[_]%'
   AND ISNULL(CONVERT(nvarchar(10), SESSION_CONTEXT(N'aprobar_migracion')), N'') <> N'36'
BEGIN
    RAISERROR (N'Migracion 36 SIN APROBAR: declara aprobar_migracion = 36 en esta sesion.', 16, 1);
    SET NOEXEC ON;
END;
GO
SET XACT_ABORT ON;
BEGIN TRAN;
DECLARE @h varbinary(32) = HASHBYTES('SHA2_256', REPLACE(REPLACE(REPLACE(REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'adm.usp_SolicitudIniciativa_Crear', N'P')), N' ', N''), NCHAR(9), N''), NCHAR(13), N''), NCHAR(10), N''));
IF @h IS NULL OR @h <> 0x518234C546F607D7FF3DA64DDB0BBE167002DA7BC31C6C897CF9A2C82050761A
   OR COL_LENGTH(N'dbo.UsuariosAdmin', N'NombreSolicitante') IS NULL
   OR OBJECT_ID(N'adm.CK_SolicitudIniciativa_Fuente', N'C') IS NULL
   OR NOT ((OBJECT_ID(N'adm.CK_SolicitudIniciativa_FuenteNombre', N'C') IS NULL AND COLUMNPROPERTY(OBJECT_ID(N'adm.SolicitudIniciativa'), N'SolicitanteNombre', 'AllowsNull') = 0) OR (OBJECT_ID(N'adm.CK_SolicitudIniciativa_FuenteNombre', N'C') IS NOT NULL AND COLUMNPROPERTY(OBJECT_ID(N'adm.SolicitudIniciativa'), N'SolicitanteNombre', 'AllowsNull') = 1))
BEGIN
    ROLLBACK;
    IF @h = 0x0484CDBC320573111B3EE245FA1E225F83DC65E7078213DE1C4C275C70E51D5A
        RAISERROR (N'Migracion 36: ya aplicada (_Crear con el hash de sql/36). No se toca nada.', 16, 1);
    ELSE IF @h IS NULL OR @h <> 0x518234C546F607D7FF3DA64DDB0BBE167002DA7BC31C6C897CF9A2C82050761A
        RAISERROR (N'Migracion 36: adm.usp_SolicitudIniciativa_Crear no es la de sql/29. No se toca nada.', 16, 1);
    ELSE IF COL_LENGTH(N'dbo.UsuariosAdmin', N'NombreSolicitante') IS NULL
        RAISERROR (N'Migracion 36: falta dbo.UsuariosAdmin.NombreSolicitante; aplica sql/35 antes. No se toca nada.', 16, 1);
    ELSE
        RAISERROR (N'Migracion 36: adm.SolicitudIniciativa no esta como la deja sql/29 ni como la deja sql/36. No se toca nada.', 16, 1);
    SET NOEXEC ON;
END;
GO
IF @@TRANCOUNT = 0 BEGIN RAISERROR (N'Migracion 36: transaccion cerrada.', 16, 1); SET NOEXEC ON; END;
GO
/* ---------- 1. Funciones de normalizacion (= IdentidadAcuse) ---------- */
IF OBJECT_ID(N'adm.fn_ClaveNombre', N'FN') IS NOT NULL DROP FUNCTION adm.fn_ClaveNombre;
IF OBJECT_ID(N'adm.fn_ClaveCorreo', N'FN') IS NOT NULL DROP FUNCTION adm.fn_ClaveCorreo;
GO
IF @@TRANCOUNT = 0 BEGIN RAISERROR (N'Migracion 36: transaccion cerrada.', 16, 1); SET NOEXEC ON; END;
GO
CREATE FUNCTION adm.fn_ClaveCorreo (@s nvarchar(4000))
RETURNS nvarchar(4000)
WITH SCHEMABINDING, RETURNS NULL ON NULL INPUT
AS
BEGIN
    -- = IdentidadAcuse.ClaveCorreo: Trim() de char.IsWhiteSpace y ToLowerInvariant
    -- (tabla generada de .NET, 973 caracteres).
    -- Atajo, sin tablas ni ciclo: solo ASCII imprimible (U+0020-U+007E, la
    -- inmensa mayoria). Ahi el unico espacio es U+0020 y ToLowerInvariant
    -- solo toca A-Z: da lo mismo que el ciclo de abajo.
    IF @s COLLATE Latin1_General_100_BIN2 NOT LIKE N'%[^ -~]%'
        RETURN NULLIF(LOWER(LTRIM(RTRIM(@s COLLATE Latin1_General_100_BIN2))), N'');
    DECLARE @de nvarchar(4000) = CONVERT(nvarchar(4000), 
         + 
         + 
         + ) COLLATE Latin1_General_100_BIN2;
    DECLARE @a nvarchar(4000) = CONVERT(nvarchar(4000), 
         + 
         + 
         + ) COLLATE Latin1_General_100_BIN2;
    DECLARE @ws nvarchar(30) = CONVERT(nvarchar(30), 0x200009000A000B000C000D008500A000801600200120022003200420052006200720082009200A20282029202F205F200030) COLLATE Latin1_General_100_BIN2;
    DECLARE @t nvarchar(4000) = @s COLLATE Latin1_General_100_BIN2, @r nvarchar(4000) = N'', @i int = 1, @n int, @ch nchar(1), @p int;
    WHILE LEN(@t + N'x') > 1 AND CHARINDEX(LEFT(@t, 1) COLLATE Latin1_General_100_BIN2, @ws COLLATE Latin1_General_100_BIN2) > 0 SET @t = SUBSTRING(@t, 2, 4000);
    WHILE LEN(@t + N'x') > 1 AND CHARINDEX(RIGHT(@t, 1) COLLATE Latin1_General_100_BIN2, @ws COLLATE Latin1_General_100_BIN2) > 0 SET @t = LEFT(@t, LEN(@t + N'x') - 2);
    SET @n = LEN(@t + N'x') - 1;
    WHILE @i <= @n
    BEGIN
        SET @ch = SUBSTRING(@t, @i, 1);
        -- ASCII imprimible: sin buscar en la tabla (A-Z -> a-z, lo demas igual).
        IF UNICODE(@ch) BETWEEN 32 AND 126 SET @r = @r + LOWER(@ch COLLATE Latin1_General_100_BIN2);
        ELSE
        BEGIN
            SET @p = CHARINDEX(@ch COLLATE Latin1_General_100_BIN2, @de COLLATE Latin1_General_100_BIN2);
            SET @r = @r + CASE WHEN @p > 0 THEN SUBSTRING(@a, @p, 1) ELSE @ch END;
        END;
        SET @i += 1;
    END;
    RETURN NULLIF(@r, N'');
END;
GO
IF @@TRANCOUNT = 0 BEGIN RAISERROR (N'Migracion 36: transaccion cerrada.', 16, 1); SET NOEXEC ON; END;
GO
CREATE FUNCTION adm.fn_ClaveNombre (@s nvarchar(4000))
RETURNS nvarchar(4000)
WITH SCHEMABINDING, RETURNS NULL ON NULL INPUT
AS
BEGIN
    -- = IdentidadAcuse.ClaveNombre: NBSP y char.IsWhiteSpace -> un espacio, extremos
    -- fuera, marcas combinantes fuera, NFD sin marcas + ToUpperInvariant (tabla
    -- generada de .NET, 2044 caracteres). Comparar con COLLATE Latin1_General_100_BIN2.
    -- Atajo, sin tablas ni ciclo: solo ASCII imprimible (U+0020-U+007E). Ahi
    -- no hay NBSP, marcas ni otro espacio que U+0020: extremos fuera, cada
    -- racha de espacios a uno (NCHAR(1) no puede venir: no es imprimible) y
    -- ToUpperInvariant solo toca a-z. Da lo mismo que el ciclo de abajo.
    IF @s COLLATE Latin1_General_100_BIN2 NOT LIKE N'%[^ -~]%'
        RETURN NULLIF(UPPER(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@s COLLATE Latin1_General_100_BIN2)),
                      N' ', N' ' + NCHAR(1)), NCHAR(1) + N' ', N''), NCHAR(1), N'')), N'');
    DECLARE @de nvarchar(4000) = CONVERT(nvarchar(4000), 
         + 
         + 
         + 
         + 
         + 
         + 
         + 
         + 0x39FB3AFB3BFB3CFB3EFB40FB41FB43FB44FB46FB47FB48FB49FB4AFB4BFB4CFB4DFB4EFB41FF42FF43FF44FF45FF46FF47FF48FF49FF4AFF4BFF4CFF4DFF4EFF4FFF50FF51FF52FF53FF54FF55FF56FF57FF58FF59FF5AFF) COLLATE Latin1_General_100_BIN2;
    DECLARE @a nvarchar(4000) = CONVERT(nvarchar(4000), 
         + 
         + 
         + 
         + 
         + 
         + 
         + 
         + 0xD905DA05DB05DC05DE05E005E105E305E405E605E705E805E905EA05D505D105DB05E40521FF22FF23FF24FF25FF26FF27FF28FF29FF2AFF2BFF2CFF2DFF2EFF2FFF30FF31FF32FF33FF34FF35FF36FF37FF38FF39FF3AFF) COLLATE Latin1_General_100_BIN2;
    DECLARE @marcas nvarchar(4000) = CONVERT(nvarchar(4000), 
         + 
         + 
         + ) COLLATE Latin1_General_100_BIN2;
    DECLARE @ws nvarchar(30) = CONVERT(nvarchar(30), 0x200009000A000B000C000D008500A000801600200120022003200420052006200720082009200A20282029202F205F200030) COLLATE Latin1_General_100_BIN2;
    DECLARE @t nvarchar(4000) = @s COLLATE Latin1_General_100_BIN2, @r nvarchar(4000) = N'', @i int = 1, @n int, @ch nchar(1), @p int;
    SET @n = LEN(@t + N'x') - 1;
    WHILE @i <= @n
    BEGIN
        SET @ch = SUBSTRING(@t, @i, 1);
        -- ASCII imprimible sin el espacio: ni marca ni tabla (a-z -> A-Z).
        IF UNICODE(@ch) BETWEEN 33 AND 126 SET @ch = UPPER(@ch COLLATE Latin1_General_100_BIN2);
        ELSE IF CHARINDEX(@ch COLLATE Latin1_General_100_BIN2, @marcas COLLATE Latin1_General_100_BIN2) > 0 SET @ch = NULL;
        ELSE IF CHARINDEX(@ch COLLATE Latin1_General_100_BIN2, @ws COLLATE Latin1_General_100_BIN2) > 0 SET @ch = N' ';
        ELSE
        BEGIN
            SET @p = CHARINDEX(@ch COLLATE Latin1_General_100_BIN2, @de COLLATE Latin1_General_100_BIN2);
            IF @p > 0 SET @ch = SUBSTRING(@a, @p, 1);
        END;
        IF @ch IS NOT NULL AND NOT (@ch = N' ' AND (LEN(@r + N'x') = 1 OR RIGHT(@r, 1) = N' ')) SET @r = @r + @ch;
        SET @i += 1;
    END;
    RETURN NULLIF(RTRIM(@r), N'');
END;
GO
IF @@TRANCOUNT = 0 BEGIN RAISERROR (N'Migracion 36: transaccion cerrada.', 16, 1); SET NOEXEC ON; END;
GO
/* ---------- 2. adm.SolicitudIniciativa ---------- */
IF COLUMNPROPERTY(OBJECT_ID(N'adm.SolicitudIniciativa'), N'SolicitanteNombre', 'AllowsNull') = 0
    ALTER TABLE adm.SolicitudIniciativa ALTER COLUMN SolicitanteNombre nvarchar(255) NULL;
ALTER TABLE adm.SolicitudIniciativa DROP CONSTRAINT CK_SolicitudIniciativa_Fuente;
ALTER TABLE adm.SolicitudIniciativa WITH CHECK ADD CONSTRAINT CK_SolicitudIniciativa_Fuente
    CHECK (FuenteCorreos IN ('CATPERSONA', 'USUARIOSADMIN'));
IF OBJECT_ID(N'adm.CK_SolicitudIniciativa_FuenteNombre', N'C') IS NOT NULL
    ALTER TABLE adm.SolicitudIniciativa DROP CONSTRAINT CK_SolicitudIniciativa_FuenteNombre;
ALTER TABLE adm.SolicitudIniciativa WITH CHECK ADD CONSTRAINT CK_SolicitudIniciativa_FuenteNombre
    CHECK (FuenteCorreos = 'USUARIOSADMIN' OR SolicitanteNombre IS NOT NULL);
GO
IF @@TRANCOUNT = 0 BEGIN RAISERROR (N'Migracion 36: transaccion cerrada.', 16, 1); SET NOEXEC ON; END;
GO
/* ---------- 2. adm.usp_SolicitudIniciativa_Crear (sql/36) ---------- */
ALTER PROCEDURE adm.usp_SolicitudIniciativa_Crear
    @Usuario            nvarchar(256),      -- IdentidadWindows.Original (la cuenta de IIS)
    @Token              uniqueidentifier,
    @TipoIniciativa     nvarchar(100),
    @ProductOwner       nvarchar(255),
    @ServiceOwner       nvarchar(255),
    @Categoria          nvarchar(450),
    @Director           nvarchar(255),
    @Titulo             nvarchar(max),
    @Descripcion        nvarchar(max),
    @Observaciones      nvarchar(max),
    @Volumetria         int,
    @PctDisminucion     decimal(9,4),
    @RcaExtension       nvarchar(10),
    @SolicitanteNombre  nvarchar(255),      -- CATPERSONA: el del sitio. USUARIOSADMIN: NO se usa (sql/36)
    @SolicitanteCorreo  nvarchar(255),
    @ProductOwnerCorreo nvarchar(255),
    @NumeroSolicitud    int          OUTPUT,
    @Nuevo              bit          OUTPUT,
    @FechaUtc           datetime2(0) OUTPUT,
    @FuenteSolicitante  varchar(16)   = NULL OUTPUT,   -- sql/36: CATPERSONA | USUARIOSADMIN
    @NombreGuardado     nvarchar(255) = NULL OUTPUT    -- sql/36: el SolicitanteNombre guardado (NULL valido)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Usuario = NULLIF(LTRIM(RTRIM(@Usuario)), N'');
    SET @TipoIniciativa = NULLIF(LTRIM(RTRIM(@TipoIniciativa)), N'');
    SET @ProductOwner = NULLIF(LTRIM(RTRIM(@ProductOwner)), N'');
    SET @ServiceOwner = NULLIF(LTRIM(RTRIM(@ServiceOwner)), N'');
    SET @Categoria = NULLIF(LTRIM(RTRIM(@Categoria)), N'');
    SET @Director = NULLIF(LTRIM(RTRIM(@Director)), N'');
    SET @Titulo = NULLIF(LTRIM(RTRIM(@Titulo)), N'');
    SET @Descripcion = NULLIF(LTRIM(RTRIM(@Descripcion)), N'');
    SET @Observaciones = NULLIF(LTRIM(RTRIM(@Observaciones)), N'');
    SET @RcaExtension = NULLIF(LTRIM(RTRIM(@RcaExtension)), N'');
    SET @SolicitanteNombre = NULLIF(LTRIM(RTRIM(@SolicitanteNombre)), N'');
    SET @SolicitanteCorreo = LOWER(NULLIF(LTRIM(RTRIM(@SolicitanteCorreo)), N''));
    SET @ProductOwnerCorreo = LOWER(NULLIF(LTRIM(RTRIM(@ProductOwnerCorreo)), N''));
    SET @NumeroSolicitud = NULL; SET @Nuevo = 0; SET @FechaUtc = NULL;
    SET @FuenteSolicitante = NULL; SET @NombreGuardado = NULL;

    IF @Usuario IS NULL THROW 51401, N'Sin usuario no se guarda la solicitud.', 1;
    IF @Token IS NULL THROW 51402, N'Falta el token de la solicitud.', 1;
    IF @TipoIniciativa IS NULL OR @ProductOwner IS NULL OR @ServiceOwner IS NULL OR @Categoria IS NULL
       OR @Director IS NULL OR @Titulo IS NULL OR @Descripcion IS NULL OR @Observaciones IS NULL
       OR @SolicitanteCorreo IS NULL OR @ProductOwnerCorreo IS NULL
        THROW 51403, N'Falta un campo obligatorio de la solicitud.', 1;
    IF @Volumetria IS NULL OR @Volumetria < 0 OR @PctDisminucion IS NULL OR @PctDisminucion < 0 OR @PctDisminucion > 1
        THROW 51404, N'La volumetria o el porcentaje estan fuera de rango.', 1;

    BEGIN TRY
        BEGIN TRAN;
            -- El mismo borrador otra vez: la misma solicitud.
            DECLARE @cuentaToken nvarchar(256);
            SELECT @NumeroSolicitud = s.NumeroSolicitud, @FechaUtc = s.FechaUtc, @cuentaToken = s.SolicitanteCuenta,
                   @FuenteSolicitante = s.FuenteCorreos, @NombreGuardado = s.SolicitanteNombre
            FROM adm.SolicitudIniciativa AS s WITH (UPDLOCK, HOLDLOCK)
            WHERE s.Token = @Token;
            IF @NumeroSolicitud IS NOT NULL
            BEGIN
                IF UPPER(@cuentaToken) <> UPPER(@Usuario)
                    THROW 51409, N'El token de la solicitud pertenece a otra cuenta.', 1;
                COMMIT;
                RETURN;
            END;

            -- Solicitante (sql/36). La FUENTE la decide la base con sus tablas
            -- y la MISMA regla del sitio (IdentidadAcuse.Resolver, con
            -- adm.fn_ClaveCorreo / adm.fn_ClaveNombre), no la presencia del nombre:
            --   CATPERSONA     el correo es el de la cuenta (cuenta@soriana.com, como
            --                  sql/37), es de UNA fila vigente de CatPersona y su
            --                  nombre no se repite en otra fila vigente. Exige el
            --                  nombre que resolvio el sitio (51403 sin el).
            --   USUARIOSADMIN  si no: @Usuario tiene filas en dbo.UsuariosAdmin,
            --                  TODAS ADM o MOD (RolAdmin), con UN solo CorreoUsuario
            --                  y es @SolicitanteCorreo. El nombre sale de
            --                  UsuariosAdmin.NombreSolicitante (NULL valido); el del
            --                  sitio NO se usa. Dos nombres distintos: 51418.
            --   otra cosa      51417 si la cuenta esta en UsuariosAdmin (mal
            --                  configurada); si no, 51405 como en sql/29.
            DECLARE @fuente varchar(16), @clave nvarchar(4000) = adm.fn_ClaveCorreo(@SolicitanteCorreo),
                    @porCorreo int, @claveNombre nvarchar(4000), @nombres int, @nombre nvarchar(255),
                    @cta nvarchar(256), @yoCorreo nvarchar(4000);
            SET @cta = CASE WHEN CHARINDEX(N'\', @Usuario) > 0 THEN RIGHT(@Usuario, CHARINDEX(N'\', REVERSE(@Usuario)) - 1) ELSE @Usuario END;
            SET @yoCorreo = adm.fn_ClaveCorreo(@cta) + N'@soriana.com';
            SELECT @porCorreo = COUNT(*), @claveNombre = MIN(adm.fn_ClaveNombre(p.Nombre) COLLATE Latin1_General_100_BIN2)
            FROM dbo.CatPersona AS p
            WHERE p.VigenteEnOrigen = 1 AND adm.fn_ClaveCorreo(p.Correo) COLLATE Latin1_General_100_BIN2 = @clave COLLATE Latin1_General_100_BIN2;
            IF @porCorreo = 1 AND @claveNombre IS NOT NULL AND @clave COLLATE Latin1_General_100_BIN2 = @yoCorreo COLLATE Latin1_General_100_BIN2
               AND (SELECT COUNT(*) FROM dbo.CatPersona AS p
                    WHERE p.VigenteEnOrigen = 1 AND adm.fn_ClaveNombre(p.Nombre) COLLATE Latin1_General_100_BIN2 = @claveNombre COLLATE Latin1_General_100_BIN2) = 1
            BEGIN
                IF @SolicitanteNombre IS NULL
                    THROW 51403, N'Falta un campo obligatorio de la solicitud.', 1;
                SET @fuente = 'CATPERSONA';
            END
            ELSE IF EXISTS (SELECT 1 FROM dbo.UsuariosAdmin AS u WHERE UPPER(LTRIM(RTRIM(u.Usuario))) = UPPER(@Usuario))
                AND NOT EXISTS (SELECT 1 FROM dbo.UsuariosAdmin AS u
                                WHERE UPPER(LTRIM(RTRIM(u.Usuario))) = UPPER(@Usuario) AND (u.Acceso IS NULL OR UPPER(LTRIM(RTRIM(u.Acceso))) NOT IN (N'ADM', N'MOD')))
                AND (SELECT COUNT(DISTINCT adm.fn_ClaveCorreo(u.CorreoUsuario) COLLATE Latin1_General_100_BIN2) FROM dbo.UsuariosAdmin AS u
                     WHERE UPPER(LTRIM(RTRIM(u.Usuario))) = UPPER(@Usuario) AND adm.fn_ClaveCorreo(u.CorreoUsuario) IS NOT NULL) = 1
                AND EXISTS (SELECT 1 FROM dbo.UsuariosAdmin AS u
                            WHERE UPPER(LTRIM(RTRIM(u.Usuario))) = UPPER(@Usuario) AND adm.fn_ClaveCorreo(u.CorreoUsuario) COLLATE Latin1_General_100_BIN2 = @clave COLLATE Latin1_General_100_BIN2)
            BEGIN
                SELECT @nombres = COUNT(DISTINCT adm.fn_ClaveNombre(u.NombreSolicitante) COLLATE Latin1_General_100_BIN2),
                       @nombre = MIN(LTRIM(RTRIM(u.NombreSolicitante)))
                FROM dbo.UsuariosAdmin AS u
                WHERE UPPER(LTRIM(RTRIM(u.Usuario))) = UPPER(@Usuario) AND adm.fn_ClaveNombre(u.NombreSolicitante) IS NOT NULL;
                IF @nombres > 1
                    THROW 51418, N'La cuenta tiene mas de un NombreSolicitante distinto en dbo.UsuariosAdmin.', 1;
                SET @SolicitanteNombre = @nombre;   -- NULL si no hay
                SET @fuente = 'USUARIOSADMIN';
            END
            ELSE IF EXISTS (SELECT 1 FROM dbo.UsuariosAdmin AS u WHERE UPPER(LTRIM(RTRIM(u.Usuario))) = UPPER(@Usuario))
                THROW 51417, N'La cuenta esta en dbo.UsuariosAdmin pero no como ADM/MOD con ese unico CorreoUsuario.', 1;
            ELSE
                THROW 51405, N'El correo del solicitante no es de una sola persona vigente de CatPersona.', 1;
            IF (SELECT COUNT(*) FROM dbo.CatPersona AS p
                WHERE p.VigenteEnOrigen = 1 AND LOWER(LTRIM(RTRIM(p.Correo))) = @ProductOwnerCorreo) <> 1
                THROW 51406, N'El correo del Product Owner no es de una sola persona vigente de CatPersona.', 1;

            -- UPDLOCK + HOLDLOCK: un alta a la vez toma el siguiente numero.
            DECLARE @ultimo int;
            SELECT @ultimo = c.Ultimo FROM adm.SolicitudIniciativaContador AS c WITH (UPDLOCK, HOLDLOCK) WHERE c.Id = 1;
            IF @ultimo IS NULL THROW 51408, N'El contador de solicitudes no tiene su fila.', 1;
            IF @ultimo >= 9999999 THROW 51407, N'Se agotaron los numeros de solicitud de 7 digitos.', 1;
            UPDATE adm.SolicitudIniciativaContador SET Ultimo = @ultimo + 1 WHERE Id = 1;
            SET @NumeroSolicitud = @ultimo + 1;

            INSERT adm.SolicitudIniciativa
                (NumeroSolicitud, Token, Estado, TipoIniciativa, ProductOwner, ServiceOwner, Categoria, Director,
                 Titulo, Descripcion, Observaciones, Volumetria, PctDisminucion, RcaExtension,
                 SolicitanteCuenta, SolicitanteNombre, SolicitanteCorreo, ProductOwnerCorreo, FuenteCorreos)
            VALUES
                (@NumeroSolicitud, @Token, 'ENVIADA', @TipoIniciativa, @ProductOwner, @ServiceOwner, @Categoria, @Director,
                 @Titulo, @Descripcion, @Observaciones, @Volumetria, @PctDisminucion, @RcaExtension,
                 @Usuario, @SolicitanteNombre, @SolicitanteCorreo, @ProductOwnerCorreo, @fuente);
            INSERT adm.SolicitudIniciativaEvento (NumeroSolicitud, Evento, EstadoAnterior, EstadoNuevo, Usuario)
            VALUES (@NumeroSolicitud, 'ENVIADA', NULL, 'ENVIADA', @Usuario);
            SELECT @FechaUtc = FechaUtc FROM adm.SolicitudIniciativa WHERE NumeroSolicitud = @NumeroSolicitud;
            SET @Nuevo = 1;
            SET @FuenteSolicitante = @fuente; SET @NombreGuardado = @SolicitanteNombre;
        COMMIT;   -- cualquier error: contador, solicitud y evento se revierten juntos
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SET @NumeroSolicitud = NULL; SET @Nuevo = 0; SET @FechaUtc = NULL;
        SET @FuenteSolicitante = NULL; SET @NombreGuardado = NULL;
        THROW;
    END CATCH;
END;
GO
IF @@TRANCOUNT = 0 BEGIN RAISERROR (N'Migracion 36: transaccion cerrada.', 16, 1); SET NOEXEC ON; END;
GO
/* ---------- 3. Postcondicion ---------- */
IF HASHBYTES('SHA2_256', REPLACE(REPLACE(REPLACE(REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'adm.usp_SolicitudIniciativa_Crear', N'P')), N' ', N''), NCHAR(9), N''), NCHAR(13), N''), NCHAR(10), N'')) = 0x0484CDBC320573111B3EE245FA1E225F83DC65E7078213DE1C4C275C70E51D5A
   AND (SELECT COUNT(*) FROM sys.parameters WHERE object_id = OBJECT_ID(N'adm.usp_SolicitudIniciativa_Crear')) = 21
   AND OBJECT_ID(N'adm.fn_ClaveCorreo', N'FN') IS NOT NULL AND OBJECT_ID(N'adm.fn_ClaveNombre', N'FN') IS NOT NULL AND OBJECT_ID(N'adm.CK_SolicitudIniciativa_FuenteNombre', N'C') IS NOT NULL AND COLUMNPROPERTY(OBJECT_ID(N'adm.SolicitudIniciativa'), N'SolicitanteNombre', 'AllowsNull') = 1
   AND NOT EXISTS (SELECT 1 FROM sys.check_constraints WHERE parent_object_id = OBJECT_ID(N'adm.SolicitudIniciativa')
                   AND name IN (N'CK_SolicitudIniciativa_Fuente', N'CK_SolicitudIniciativa_FuenteNombre') AND is_not_trusted = 1)
BEGIN
    COMMIT;
    SELECT Script = N'Migracion 36', Resultado = 'APLICADA';
END
ELSE
BEGIN
    ROLLBACK;
    RAISERROR (N'Migracion 36: _Crear, funciones, columna o CHECK no quedo como se esperaba; ROLLBACK de todo.', 16, 1);
END;
GO
SET NOEXEC OFF;
GO
